// MOVE (tipos owned: String, Vec, Box, arquivos...)
let s1 = String::from("olá");
let s2 = s1;           // ownership MOVE de s1 para s2
// println!("{}", s1); // ERRO: value moved
println!("{}", s2);    // ok

// COPY (tipos bit-copiáveis baratos: i32, bool, char, f64, &T...)
let x: i32 = 42;
let y = x;             // COPY — ambos válidos
println!("{} {}", x, y);

// derive(Clone) dá .clone() explícito
#[derive(Clone)]
struct Config { text: String }
let a = Config { text: "prod".into() };
let b = a.clone();     // cópia explícita, custo visível

// sem borrow: você teria que devolver o valor
fn len_bad(s: String) -> (usize, String) {
    (s.len(), s)           // feio, força quem chama a receber de volta
}

// com borrow: empresta, não move
fn len_ok(s: &str) -> usize {
    s.len()
}

fn main() {
    let nome = String::from("fernando");
    let n = len_ok(&nome); // empresta, nome continua válido
    println!("{} tem {} chars", nome, n);
}

let mut v = vec![1, 2, 3];

let r1 = &v;         // borrow compartilhado
let r2 = &v;         // outro borrow compartilhado — OK (só leitura)
println!("{:?} {:?}", r1, r2);

let m = &mut v;      // borrow exclusivo — OK porque r1/r2 não são mais usados (NLL)
m.push(4);

// ERRO clássico: usar &v e &mut v ao mesmo tempo
// let r = &v;
// let m = &mut v;   // ERRO: cannot borrow `v` as mutable while immutable borrow exists
// println!("{:?}", r);

// ❌ tentativa vinda de Python/JS
fn primeiro(v: &Vec<i32>) -> &i32 { &v[0] }

fn main() {
    let mut v = vec![1, 2, 3];
    let p = primeiro(&v);  // borrow imutável vivo
    v.push(4);             // ERRO: &mut v enquanto &v existe
    println!("{}", p);
}

// ✅ versão idiomática: escopo do borrow termina antes do push
fn main_ok() {
    let mut v = vec![1, 2, 3];
    let primeiro_val = v[0]; // Copy de i32, borrow vive 1 linha
    v.push(4);
    println!("primeiro era {}", primeiro_val);
}

// Rc<T>: múltiplos donos em single-thread (ref count)
// Arc<T>: idem thread-safe (atomic ref count)
// RefCell<T>: mutabilidade interior single-thread (runtime check)
// Mutex<T> / RwLock<T>: mutabilidade interior multi-thread

use std::sync::Arc;
use std::sync::Mutex;

let config = Arc::new(Mutex::new(String::from("prod")));
let c2 = Arc::clone(&config);
std::thread::spawn(move || {
    let mut guard = c2.lock().unwrap();
    guard.push_str("-v2");
});
